// Read-only mirror of the app's reporting rules (lib/services/finance_rules.dart
// and financial_analysis.dart). Pure functions, no I/O: they run in Deno on the
// server and in Node for the parity test against fixtures generated by Dart.
// Money is accumulated in integer cents.

export type Row = Record<string, unknown>;

export interface Ledger {
  mainCurrency: string;
  accounts: Row[]; // SQLite rows without balance
  balances: Record<string, number>; // account id -> micros
  categories: Row[];
  transactions: Row[];
  metadata: Row[];
  recurring: Row[];
  investments: Row[];
  investmentOperations: Row[];
  budgets?: Row[];
  goals?: Row[];
  contributions?: Row[];
  recurringHistory?: Row[];
}

export interface Meta {
  subcategory: string;
  status: string;
  dueDate: string | null;
  expenseClass: string;
  excludeFromSpending: boolean;
  installmentCurrent: number | null;
  installmentTotal: number | null;
  source: string;
}

export const text = (v: unknown): string => (typeof v === "string" ? v : "");
export const num = (v: unknown): number => (typeof v === "number" && isFinite(v) ? v : 0);
export const cents = (amount: number): number => Math.round(amount * 100);
export const day = (iso: string): string => iso.slice(0, 10);

export function meta(row: Row | undefined): Meta {
  const int = (v: unknown) => (typeof v === "number" ? v : null);
  return {
    subcategory: text(row?.subcategory),
    status: text(row?.status) || "paid",
    dueDate: typeof row?.due_date === "string" ? row.due_date : null,
    expenseClass: text(row?.expense_class) || "normal",
    excludeFromSpending: row?.exclude_from_spending === 1,
    installmentCurrent: int(row?.installment_current),
    installmentTotal: int(row?.installment_total),
    source: text(row?.source) || "manual",
  };
}

export function isImplicitNeutral(tx: Row): boolean {
  const t = `${text(tx.description)} ${text(tx.note)}`.toLowerCase();
  return t.includes("transfer out") ||
    t.includes("transfer in") ||
    t.startsWith("transferência enviada") ||
    t.startsWith("transferência recebida") ||
    (t.includes("fatura") && t.includes("pagamento")) ||
    t.includes("pagamento da fatura") ||
    t.includes("pagamento de fatura");
}

export const isNeutral = (tx: Row, m: Meta): boolean => m.excludeFromSpending || isImplicitNeutral(tx);

export const isRefund = (tx: Row, m: Meta): boolean =>
  tx.type === "income" && (m.source === "notification_refund" || tx.note === "Estorno / reembolso revisado");

export interface Filter {
  from: string; // YYYY-MM-DD inclusive
  to: string; // YYYY-MM-DD inclusive
  accountId?: string;
  categoryId?: string;
  type?: string;
}

export interface Analysis {
  income: number;
  expense: number;
  refunds: number;
  pendingExpense: number;
  extraordinary: number;
  recurring: number;
  transfers: number;
  result: number;
  categories: Record<string, number>;
  unconverted: Record<string, number>; // currency -> cents, never summed in
  realizedCount: number;
  pendingCount: number;
}

export function metadataIndex(ledger: Ledger): Map<string, Row> {
  return new Map(ledger.metadata.map((m) => [text(m.transaction_id), m]));
}

export function currencyOf(ledger: Ledger, tx: Row): string {
  const own = text(tx.currency);
  if (own) return own;
  const account = ledger.accounts.find((a) => a.id === tx.account_id);
  return text(account?.currency) || ledger.mainCurrency;
}

export function matches(tx: Row, f: Filter): boolean {
  const d = day(text(tx.date));
  return d >= f.from && d <= f.to &&
    (f.accountId === undefined || tx.account_id === f.accountId) &&
    (f.categoryId === undefined || tx.category_id === f.categoryId) &&
    (f.type === undefined || tx.type === f.type);
}

/// Same branches, in the same order, as FinancialAnalysis in Dart.
export function analyze(ledger: Ledger, f: Filter): Analysis {
  const metas = metadataIndex(ledger);
  const a: Analysis = {
    income: 0, expense: 0, refunds: 0, pendingExpense: 0, extraordinary: 0,
    recurring: 0, transfers: 0, result: 0, categories: {}, unconverted: {},
    realizedCount: 0, pendingCount: 0,
  };
  for (const tx of ledger.transactions) {
    if (!matches(tx, f)) continue;
    const id = text(tx.id);
    const m = meta(metas.get(id));
    const currency = currencyOf(ledger, tx);
    const value = cents(num(tx.amount));
    if (currency !== ledger.mainCurrency) {
      if (!isNeutral(tx, m) && m.status !== "pending" && tx.type === "expense") {
        a.unconverted[currency] = (a.unconverted[currency] ?? 0) + value;
      }
      continue;
    }
    if (isNeutral(tx, m)) {
      if (m.status !== "pending" && tx.type === "expense" && m.source.startsWith("transfer:")) {
        a.transfers += value;
      }
      continue;
    }
    if (m.status === "pending") {
      a.pendingCount++;
      if (tx.type === "expense") a.pendingExpense += value;
      continue;
    }
    a.realizedCount++;
    if (isRefund(tx, m)) {
      a.refunds += value;
      continue;
    }
    if (tx.type === "income") {
      a.income += value;
      continue;
    }
    if (tx.type !== "expense") continue;
    a.expense += value;
    const category = text(tx.category_id);
    a.categories[category] = (a.categories[category] ?? 0) + value;
    if (m.expenseClass === "extraordinary") a.extraordinary += value;
    if (m.source === "recurring" || id.startsWith("recurring:")) a.recurring += value;
  }
  a.result = a.income + a.refunds - a.expense;
  return a;
}

const pad = (n: number) => String(n).padStart(2, "0");
export const isoDay = (d: Date) => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
const lastDay = (y: number, m: number) => new Date(Date.UTC(y, m + 1, 0)).getUTCDate();

/// Month filter like FinancialAnalysis.month: current month stops at today.
export function monthFilter(month: string, today: string): Filter {
  const [y, m] = month.split("-").map(Number);
  const from = `${y}-${pad(m)}-01`;
  const end = `${y}-${pad(m)}-${pad(lastDay(y, m - 1))}`;
  return { from, to: today.slice(0, 7) === month ? today : end };
}

/// Previous month cut at the same day when the current one is partial.
export function previousMonth(f: Filter, partial: boolean): Filter {
  const [y, m] = f.from.split("-").map(Number);
  const py = m === 1 ? y - 1 : y, pm = m === 1 ? 12 : m - 1;
  const last = lastDay(py, pm - 1);
  const toDay = partial ? Math.min(Number(f.to.slice(8, 10)), last) : last;
  return { from: `${py}-${pad(pm)}-01`, to: `${py}-${pad(pm)}-${pad(Math.max(1, toDay))}` };
}

export const money = (c: number) => Math.round(c) / 100;
